parameters.text:
=Review the email triage findings and calendar schedule for today ({{ $("Initialize Daily Context").item.json.displayDate }}):

EMAIL INTELLIGENCE:
{{ JSON.stringify($("Email Triage Agent").item.json.output || {}) }}

CALENDAR SCHEDULE:
{{ JSON.stringify($("Calendar Schedule Agent").item.json.output || {}) }}

Synthesize both data sources into a unified executive daily briefing. Correlate urgent emails with scheduled meetings (e.g. attendee topics or contract deadlines before demos). Construct an integrated chronological day timeline combining meetings, email actions, and focus blocks. Rank top daily priorities, compute an overall readiness score (0-100), and write 3 strategic executive recommendations.

parameters.jsCode:
const synth = $('Briefing Synthesizer Agent').first()?.json?.output || {};
const email = $('Email Triage Agent').first()?.json?.output || {};
const cal = $('Calendar Schedule Agent').first()?.json?.output || {};
const ctx = $('Initialize Daily Context').first()?.json || {};

const dateStr = ctx.displayDate || new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const readiness = synth.readinessScore || 90;
const greeting = synth.greeting || 'Good morning! Here is your synthesized executive briefing for today.';

const priorities = synth.topPriorities || [];
const timeline = synth.dayTimeline || [];
const emailActions = email.actionItems || [];
const calendarEvents = cal.eventsChronological || [];
const recommendations = synth.executiveRecommendations || [];

const totalEmails = email.totalEmailsChecked || emailActions.length || 0;
const urgentEmails = email.urgentCount || emailActions.filter(a => a.urgency === 'Critical' || a.urgency === 'High').length || 0;
const totalMeetings = cal.totalEvents || calendarEvents.length || 0;
const focusHours = cal.focusHoursRemaining || 4.5;

function badgeClass(urgency) {
  const u = (urgency || '').toLowerCase();
  if (u.includes('crit')) return 'badge-critical';
  if (u.includes('high')) return 'badge-high';
  if (u.includes('med')) return 'badge-medium';
  return 'badge-low';
}

function timelineTypeBadge(type) {
  const t = (type || '').toLowerCase();
  if (t.includes('meet')) return 'pill-meeting';
  if (t.includes('focus')) return 'pill-focus';
  if (t.includes('action') || t.includes('dead')) return 'pill-urgent';
  return 'pill-email';
}

const prioritiesHtml = priorities.map((p, idx) => `
  <div class="priority-card">
    <div class="priority-rank">${p.rank || idx + 1}</div>
    <div class="priority-content">
      <div class="priority-header">
        <span class="priority-title">${p.title || ''}</span>
        <span class="badge ${badgeClass(p.urgency)}">${p.urgency || 'Normal'}</span>
      </div>
      <div class="priority-time">${p.timeframe || ''}</div>
      <div class="priority-desc">${p.detail || ''}</div>
    </div>
  </div>
`).join('');

const timelineHtml = timeline.map(t => `
  <div class="timeline-row">
    <div class="timeline-time">${t.time || ''}</div>
    <div class="timeline-marker"></div>
    <div class="timeline-body">
      <div class="timeline-top">
        <span class="timeline-title">${t.item || ''}</span>
        <span class="pill ${timelineTypeBadge(t.type)}">${t.type || 'Event'}</span>
      </div>
      <div class="timeline-status">${t.status || ''}</div>
    </div>
  </div>
`).join('');

const emailActionsHtml = emailActions.map(e => `
  <div class="card-item">
    <div class="card-item-header">
      <span class="card-item-title">${e.subject || 'Email Action'}</span>
      <span class="badge ${badgeClass(e.urgency)}">${e.urgency || 'Normal'}</span>
    </div>
    <div class="card-item-sub">From: <strong>${e.sender || 'Unknown'}</strong> &bull; Deadline: <strong>${e.deadline || 'Today'}</strong></div>
    <div class="card-item-desc">${e.actionRequired || ''}</div>
  </div>
`).join('');

const calendarEventsHtml = calendarEvents.map(c => `
  <div class="card-item">
    <div class="card-item-header">
      <span class="card-item-title">${c.title || 'Meeting'}</span>
      <span class="badge ${badgeClass(c.importance)}">${c.importance || 'Normal'}</span>
    </div>
    <div class="card-item-sub">${c.startTime || ''} - ${c.endTime || ''} &bull; ${c.location || 'Online'}</div>
    ${c.prepNotes ? `<div class="card-item-desc"><strong>Prep:</strong> ${c.prepNotes}</div>` : ''}
  </div>
`).join('');

const recommendationsHtml = recommendations.map((r, i) => `
  <li class="recom-item">
    <span class="recom-num">${i + 1}</span>
    <span class="recom-text">${r}</span>
  </li>
`).join('');

const fullHtml = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Daily Executive Briefing Dashboard</title>
  <style>
    :root {
      --bg: #0f172a;
      --card-bg: #1e293b;
      --card-sub: #283548;
      --text: #f8fafc;
      --text-muted: #94a3b8;
      --primary: #38bdf8;
      --accent: #818cf8;
      --critical: #f43f5e;
      --high: #fb923c;
      --medium: #facc15;
      --low: #34d399;
      --border: #334155;
    }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.5;
      padding: 24px;
    }
    .container { max-width: 1200px; margin: 0 auto; }
    header {
      background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);
      border: 1px solid var(--border);
      border-radius: 16px;
      padding: 28px 32px;
      margin-bottom: 24px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 16px;
    }
    .header-title h1 { font-size: 28px; font-weight: 700; color: #fff; margin-bottom: 4px; }
    .header-title p { color: var(--text-muted); font-size: 15px; }
    .header-meta { display: flex; align-items: center; gap: 16px; }
    .date-badge {
      background: rgba(56, 189, 248, 0.1);
      border: 1px solid rgba(56, 189, 248, 0.3);
      color: var(--primary);
      padding: 8px 16px;
      border-radius: 9999px;
      font-size: 14px;
      font-weight: 600;
    }
    .score-circle {
      background: linear-gradient(135deg, #059669 0%, #10b981 100%);
      color: #fff;
      padding: 10px 18px;
      border-radius: 12px;
      text-align: center;
      font-weight: 700;
      font-size: 14px;
      box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3);
    }
    .greeting-card {
      background: rgba(56, 189, 248, 0.05);
      border-left: 4px solid var(--primary);
      padding: 16px 20px;
      border-radius: 0 12px 12px 0;
      margin-bottom: 24px;
      font-size: 16px;
      color: #e2e8f0;
    }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
      gap: 16px;
      margin-bottom: 24px;
    }
    .stat-card {
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 20px;
      transition: transform 0.2s;
    }
    .stat-card:hover { transform: translateY(-2px); }
    .stat-label { font-size: 13px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px; }
    .stat-val { font-size: 32px; font-weight: 700; color: #fff; }
    .stat-hint { font-size: 13px; color: var(--primary); margin-top: 4px; }
    .section-title { font-size: 20px; font-weight: 700; margin-bottom: 16px; display: flex; align-items: center; gap: 8px; }
    .priorities-container { margin-bottom: 24px; }
    .priority-card {
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 16px 20px;
      margin-bottom: 12px;
      display: flex;
      align-items: flex-start;
      gap: 16px;
    }
    .priority-rank {
      background: var(--card-sub);
      color: var(--primary);
      width: 36px;
      height: 36px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 16px;
      flex-shrink: 0;
    }
    .priority-content { flex: 1; }
    .priority-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px; }
    .priority-title { font-size: 16px; font-weight: 600; color: #fff; }
    .priority-time { font-size: 13px; color: var(--text-muted); margin-bottom: 4px; }
    .priority-desc { font-size: 14px; color: #cbd5e1; }
    .split-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 24px;
      margin-bottom: 24px;
    }
    @media (max-width: 840px) { .split-grid { grid-template-columns: 1fr; } }
    .panel {
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 24px;
    }
    .card-item {
      background: var(--card-sub);
      border: 1px solid rgba(255, 255, 255, 0.05);
      border-radius: 10px;
      padding: 14px 16px;
      margin-bottom: 12px;
    }
    .card-item-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px; }
    .card-item-title { font-weight: 600; font-size: 15px; color: #fff; }
    .card-item-sub { font-size: 13px; color: var(--text-muted); margin-bottom: 6px; }
    .card-item-desc { font-size: 13px; color: #cbd5e1; }
    .timeline { position: relative; padding-left: 20px; }
    .timeline-row { display: flex; align-items: flex-start; margin-bottom: 16px; position: relative; }
    .timeline-time { width: 130px; font-size: 13px; font-weight: 600; color: var(--primary); flex-shrink: 0; }
    .timeline-marker {
      width: 12px;
      height: 12px;
      border-radius: 50%;
      background: var(--primary);
      margin: 4px 16px 0 0;
      flex-shrink: 0;
      box-shadow: 0 0 8px var(--primary);
    }
    .timeline-body { flex: 1; background: var(--card-sub); border-radius: 8px; padding: 12px 14px; }
    .timeline-top { display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px; }
    .timeline-title { font-size: 14px; font-weight: 600; color: #fff; }
    .timeline-status { font-size: 12px; color: var(--text-muted); }
    .badge { padding: 3px 8px; border-radius: 6px; font-size: 11px; font-weight: 700; text-transform: uppercase; }
    .badge-critical { background: rgba(244, 63, 94, 0.2); color: var(--critical); border: 1px solid rgba(244, 63, 94, 0.4); }
    .badge-high { background: rgba(251, 146, 60, 0.2); color: var(--high); border: 1px solid rgba(251, 146, 60, 0.4); }
    .badge-medium { background: rgba(250, 204, 21, 0.2); color: var(--medium); border: 1px solid rgba(250, 204, 21, 0.4); }
    .badge-low { background: rgba(52, 211, 153, 0.2); color: var(--low); border: 1px solid rgba(52, 211, 153, 0.4); }
    .pill { padding: 3px 8px; border-radius: 9999px; font-size: 11px; font-weight: 600; }
    .pill-meeting { background: rgba(129, 140, 248, 0.2); color: var(--accent); }
    .pill-focus { background: rgba(52, 211, 153, 0.2); color: var(--low); }
    .pill-urgent { background: rgba(244, 63, 94, 0.2); color: var(--critical); }
    .pill-email { background: rgba(56, 189, 248, 0.2); color: var(--primary); }
    .recommendations-panel {
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 24px;
      margin-bottom: 24px;
    }
    .recom-list { list-style: none; }
    .recom-item {
      display: flex;
      align-items: center;
      gap: 14px;
      padding: 10px 0;
      border-bottom: 1px solid rgba(255, 255, 255, 0.05);
      font-size: 14px;
      color: #e2e8f0;
    }
    .recom-item:last-child { border-bottom: none; }
    .recom-num {
      width: 24px;
      height: 24px;
      border-radius: 50%;
      background: rgba(56, 189, 248, 0.15);
      color: var(--primary);
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 12px;
      flex-shrink: 0;
    }
    footer {
      text-align: center;
      color: var(--text-muted);
      font-size: 13px;
      padding: 20px 0;
      border-top: 1px solid var(--border);
      margin-top: 32px;
    }
  </style>
</head>
<body>
  <div class="container">
    <header>
      <div class="header-title">
        <h1>Daily Briefing Dashboard</h1>
        <p>AI Multi-Agent Briefing &bull; Google Emails & Calendar Intelligence</p>
      </div>
      <div class="header-meta">
        <div class="date-badge">${dateStr}</div>
        <div class="score-circle">Readiness: ${readiness}%</div>
      </div>
    </header>

    <div class="greeting-card">${greeting}</div>

    <div class="stats-grid">
      <div class="stat-card">
        <div class="stat-label">Google Emails Checked</div>
        <div class="stat-val">${totalEmails}</div>
        <div class="stat-hint">${urgentEmails} urgent action items</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Scheduled Meetings</div>
        <div class="stat-val">${totalMeetings}</div>
        <div class="stat-hint">${cal.totalMeetingHours || 3.5}h meeting time</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Focus Work Available</div>
        <div class="stat-val">${focusHours}h</div>
        <div class="stat-hint">Protected productivity blocks</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Schedule Health</div>
        <div class="stat-val">${cal.conflictsDetected === 0 ? 'Optimal' : 'Conflicts'}</div>
        <div class="stat-hint">${cal.conflictsDetected || 0} overlap flags</div>
      </div>
    </div>

    <div class="priorities-container">
      <div class="section-title">Top Priorities for Today</div>
      ${prioritiesHtml}
    </div>

    <div class="panel" style="margin-bottom: 24px;">
      <div class="section-title">Master Daily Agenda & Unified Timeline</div>
      <div class="timeline">
        ${timelineHtml}
      </div>
    </div>

    <div class="split-grid">
      <div class="panel">
        <div class="section-title">Email Intelligence & Triage</div>
        ${emailActionsHtml || '<p style="color:var(--text-muted);font-size:14px;">No critical email actions pending.</p>'}
      </div>
      <div class="panel">
        <div class="section-title">Google Calendar Schedule</div>
        ${calendarEventsHtml || '<p style="color:var(--text-muted);font-size:14px;">No meetings scheduled today.</p>'}
      </div>
    </div>

    <div class="recommendations-panel">
      <div class="section-title">Executive Strategic Advice</div>
      <ul class="recom-list">
        ${recommendationsHtml}
      </ul>
    </div>

    <footer>
      Multi-Agent Daily Briefing Workflow &bull; Orchestrated via Email Specialist, Calendar Specialist & Chief of Staff Synthesizer &bull; Generated at ${new Date().toISOString()}
    </footer>
  </div>
</body>
</html>`;

return [{ json: { html: fullHtml, generatedAt: new Date().toISOString(), readinessScore: readiness } }];
